    "sys.smp": "\n// top-level default standard library import\n\nval adt = adt;                  // Abstract Data Types\nval ary = ary;                  // Array utilities\nval aryi64 = aryi64;            // Variable sized array of i64\nval aryu8 = aryu8;              // Variable sized array of u8\nval char = char;                // Character utilities\nval io = io;                    // IO library\nval libc = libc;                // libc FFI bindings\nval scan = scan;                // A simple string parser\n",
    "sys/adt/bitset.smp": "\n// A set of non-negative integers, represented one bit per value.\nstruct bitset {\n    i64[] !_bits;\n\n    new bitset = { ->\n        _bits = new i64[1];\n    };\n\n    // Return 0 for missing, non-zero for true\n    val get = { int bit ->\n        if( (bit >> 6) >= _bits# ) return false;\n        i64 mask = 1 << (bit & 63);\n        return (_bits[bit >> 6] & mask);\n    };\n\n    val _grow = { int bit ->\n        int x = bit >> 6;\n        int len = _bits#;\n        if( x < len ) return self;\n        while( x >= len ) len *= 2;\n        var bits = new i64[len];\n        for( int i=0; i<_bits#; i++ )\n            bits[i] = _bits[i];\n        _bits = bits;\n        return self;\n    };\n\n    // Set\n    val set = { int bit ->\n        i64 mask = 1 << (bit & 63);\n        _grow(bit)._bits[bit >> 6] |= mask;\n        return self;\n    };\n\n    // Test and set\n    val tset = { int bit ->\n        int idx = bit >> 6;\n        i64 mask = 1 << (bit & 63);\n        if( _grow(bit)._bits[idx] & mask )\n          return true;          // Already set\n        _bits[idx] |= mask;\n        return false;           // Was false (and now set)\n    };\n\n    val clr = { int bit ->\n        if( (bit >> 6) >= _bits# ) return self;\n        i64 mask = 1 << (bit & 63);\n        _bits[bit >> 6] &= (mask ^ -1);\n        return self;\n    };\n\n    val clear = { ->\n        for( int i=0; i<_bits#; i++ ) _bits[i] = 0;\n        return self;\n    };\n};\n",
