    "sys/ary.smp": "\n// Array utilities\n\n// Copy byte array contents.  Copies the shorter of the buffers and len\nval copy = { u8[] dst, int doff, u8[~] src, int soff, int len ->\n    if( len > dst# - doff ) len = dst# - doff;\n    if( len > src# - soff ) len = src# - soff;\n    for( int i=0; i<len; i++ )\n        dst[i+doff] = src[i+soff];\n    return dst;\n};\n\n// Compare lexigraphically array contents.  Compares up to shorter array or\n// len.  Returns <0 or >0 for first non-matching byte.  Returns <0 or >0 for\n// the larger array after that, or 0 if both arrays are fully equal.\nval cmp = { u8[~] src1, u32 off1, u8[~] src2, u32 off2, u32 len ->\n    u32 len1 = len > src1# - off1 ? src1# - off1 : len;\n    u32 len2 = len > src2# - off2 ? src2# - off2 : len;\n    u32 max = len1 > len2 ? len2 : len1;\n    for( int i=0; i<max; i++ )\n        if( src1[off1+i] != src2[off2+i] )\n            return src1[off1+i] - src2[off2+i]; // Bytes determine compare\n    return len1 - len2;                         // Length determines compare\n};\n",
    "sys/aryi64.smp": "\n// Ary/Vector of i64s\nstruct aryi64 {\n    u32 !len = 0;\n    i64[] !buf;\n\n    new aryi64 = { i64[] b ->\n        buf = b;\n    };\n\n    // Grow as needed\n    val _grow = { int len2 ->\n        if( len+len2 < buf# ) return self;\n        int newlen = buf# * 2;\n        while( len+len2 >= newlen ) newlen *= 2;\n        i64[] !buf2 = new i64[newlen];\n        for( int i=0; i<buf#; i++ )\n            buf2[i] = buf[i];\n        buf = buf2;\n        self;\n    };\n\n    // Add a i64 to aryu8\n    val add = { i64 c ->\n        _grow(1).buf[len++] = c;\n        self;\n    };\n\n    val get = { int index -> return buf[index]; };\n\n    // Write the bracketed array-list form to aryu8.\n    val str = { ->\n        // TODO: clunky default constructor syntax\n        var str = new aryu8().add('[');\n        for( int i=0; i<len; i++ )\n            str.num(buf[i]).add(',').add(' ');\n        if( len ) str.undo(2);\n        return str.add(']');\n    };\n\n    val swap = { int i, int j ->\n        i64 tmp = buf[i];\n        buf[i] = buf[j];\n        buf[j] = tmp;\n        self;\n    };\n};\n\n\n\n// Parse a comma-separated list of numbers, wrapped with square brackets,\n// with optional whitespace  e.g. \"[ -17, 0,99,12456789   ]  \".\n// parseAryI64 & aryi64.str are bijections modulo whitespace.\n// Returns null if the parse failed, without giving a clue as to why.\nval parseAryI64 = { u8[~] str ->\n    !scan !s = new scan(str);\n    if( !s.match('[') ) return null;\n    // Array of parsed results\n    var nums = new aryi64(new i64[1]);\n\n    // Parse a list of numbers\n    if( s.match(']') )          // Handle the empty list\n        return nums;\n\n    // Parse number commas \"123, \" until something else\n    while( s.x < s.buf# ) {\n        nums.add(s.number());\n        if( s.bad ) return null;\n        if( !s.match(',') )\n            break;\n    };\n    // Close the list\n    if( !s.match(']') ) return null;\n    s.skip();\n    return s.x == s.buf# ? nums : null;\n};\n\nval copy = { i64[] dst, int doff, i64[~] src, int soff, int len ->\n    for( int i=0; i<len; i++ )\n        dst[i+doff] = src[i+soff];\n    return dst;\n};\n",
    "sys/aryu8.smp": "\n// Ary/Vector of u8s - a resizable array of bytes.\nstruct aryu8 {\n    u32 !len = 0;\n    u8[] !buf;\n\n    new aryu8 = { -> buf = new u8[1]; };\n\n    // Grow as needed\n    val _grow = { int len2 ->\n        if( len+len2 < buf# ) return self;\n        int newlen = buf# * 2;\n        while( len+len2 >= newlen ) newlen *= 2;\n        u8[] !buf2 = new u8[newlen];\n        ary.copy(buf2,0,buf,0,buf#);\n        buf = buf2;\n        self;\n    };\n\n    val clear = { -> len = 0; self; };\n\n    // Add a character to aryu8\n    val add = { u8 c ->\n        _grow(1).buf[len++] = c;\n        self;\n    };\n\n    // Add all of a plain array to the aryu8\n    val addAry = { u8[~] xs ->\n        _grow(xs#);\n        ary.copy(buf,len,xs,0,xs#);\n        len += xs#;\n        self;\n    };\n\n    // Remove x bytes from the tail.\n    val undo = { int x ->\n        len = len >= x ? len-x : 0;\n        self;\n    };\n\n    // Print ASCII number into aryu8\n    val num = { i64 x ->\n        if( !x ) { add('0'); return self; }\n        if( x < 0 ) { add('-'); x = -x; }\n        i64 ten = 1, log = 0;\n        while( ten <= x ) { ten *= 10; log++; }\n        for( int i=0; i<log; i++ ) {\n            ten /= 10;\n            i64 q = x/ten;\n            u8 digit = q+'0';\n            add(digit);\n            x -= q*ten;\n        }\n        self;\n    };\n\n    // Write to fd, returns the number of bytes written (len).\n    val write = { i32 fd ->\n        i64 ptr = buf; // Cast buffer pointer to i64 for native C call\n        libc.write(fd,ptr,len);\n    };\n};\n\n\n// Parse one integer, ignore trailing data; returns 0 with an empty string.\n// If you want a more robust parsing, use the `scan` class\nval atoi = { u8[~] str ->\n    int x = 0;\n    while( x < str# && str[x] <= ' ' ) x++;\n    if( x == str# ) return 0;\n    bool neg = false;\n    if( str[x]=='-' ) { neg=true; x++; }\n    i64 n = 0;\n    while( x < str# && '0' <= str[x] <= '9' )\n        n = n*10 + str[x++]-'0';\n    return neg ? -n : n;\n};\n\n// Zero-terminate string for libc strings.  No error checking, just copies and\n// appends a zero.\n{ u8[~] -> u8[] } str0 = { u8[~] str ->\n  u8[] !strz = new u8[str#+1];\n  ary.copy(strz,0,str,0,str#);\n  strz[str#] = '\\0';\n  strz;\n};\n",
