    "sys/io.smp": "\n// Simple I/O Library\n\n// Write byte array to stdout\nval p          = { u8[~] str -> write(1,str); };\nval p_noInline = { u8[~] str -> write(1,str); };\n\n// Return fd contents as a u8[].\nval read = { i32 fd ->\n    var buf = new u8[8*1024];\n    i64 ptr = buf;\n    int len = 0;\n    while( true ) {\n        i32 rez = libc.read(fd,ptr,buf#);\n        if( rez > buf# ) libc._exit(libc.errno());\n        len += rez;\n        if( rez < buf# )\n            break;\n        libc._exit(-2); // Need to implement for more than 8K input\n    }\n    var out = new u8[len];\n    ary.copy(out,0,buf,0,len);\n};\n\n// Write all of str to fd.\nval write = { i32 fd, u8[~] str ->\n  i64 ptr = str;                // Convert array pointer to a i64 for the native call\n  libc.write(fd,ptr,str#);\n};\n\n// Write all of str to fd.\nval writeOff = { i32 fd, u8[~] str, u32 off, u32 len ->\n  i64 ptr = str;                // Convert array pointer to a i64 for the native call\n  ptr += off;                   // Skip offset\n  // Cap at available length\n  if( len > str# - off ) len = str# - off;\n  // Do the write\n  libc.write(fd,ptr,len);\n};\n\n// Return stdin as a u8[].\nval stdin = { -> read(0); };\n\n// Create file for writing.  Return fd, or -1 and errno has the error code\nval create = { u8[~] str ->\n    i64 ptr = sys.aryu8.str0(str);\n    i32 perms = 6*64 + 6*8 + 6; // 0666\n    return libc.creat(ptr, perms);\n};\n\n// Open file for reading.  Return fd, or -1 and errno has the error code\nval open = { u8[~] str ->\n    i64 ptr = sys.aryu8.str0(str);\n    return libc.open(ptr, sys.libc.O_RDONLY, 0);\n};\n\n// Close an open fd.  Return 0, or -1 and errno has the error code\nval close = { i32 fd -> return libc.close(fd); };\n\n// Remove a file.  Return 0, or -1 and errno has the error code\nval remove = { u8[~] str ->\n    i64 ptr = sys.aryu8.str0(str);\n    return libc.unlink(ptr);\n};\n",
    "sys/libc.smp": "\n// libc bindings:\n//   https://www.man7.org/linux/man-pages/man2/<libc call>.2.html\n\n// The buffers are int-versions of zero-terminated strings.\n//     int buf = aryu8.str0(\"some_file\");\n// buf mode perm-> fd\n{  i64 i32  i32 -> i32 } open = \"C\";\n// buf perm -> fd\n{  i64 i32 -> i32 } creat = \"C\";\n\n// fd  buf len -> len\n{  i32 i64 u32 -> i32 } write = \"C\";\n// fd  buf len -> len\n{  i32 i64 u32 -> i32 } read = \"C\";\n// fd  -> err\n{  i32 -> i32 } close = \"C\";\n// path -> err\n{  i64 -> i32 } unlink = \"C\";\n\ni32 O_RDONLY = 0;\ni32 O_WRONLY = 1;\ni32 O_RDWR   = 2;\ni32 O_CREAT = 512; // 02000 on x86_64-pc-cygwin\ni32 O_TRUNC = 1024; // 04000 on x86_64-pc-cygwin\n\ni32 STDIN  = 0;\ni32 STDOUT = 1;\ni32 STDERR = 2;\n\n// status\n{  i32 -> i32 } _exit = \"C\";\n// errno is not an ordinary C data symbol; read it through the native runtime.\n{ i32 } simple_errno = \"C\";\nval errno = { -> simple_errno(); };\n// addr len prot flags fd  off -> void*\n{  i64  i64 i32  i32   i32 i32 -> i64 } mmap = \"C\";\n// mmap flags\ni32 PROT_EXEC = 4;\ni32 PROT_READ = 1;\ni32 PROT_WRITE= 2;\ni32 PROT_NONE = 0;\ni32 MAP_PRIVATE = 2;\ni32 MAP_ANON = 32;\n",
    "sys/scan.smp": "\n// Scanner; a simple string parser.\nstruct scan {\n    int !x;                     // Cursor\n    bool !bad;                  // True after a malformed token\n    u8[~] buf;                  // Buffer to parse\n\n    new scan = { u8[~] b -> buf = b; };\n\n    // Skip whitespace\n    val skip = { ->\n        while( x < buf# && buf[x] <= ' ' )\n            x++;\n        return self;\n    };\n\n    // True if find required character, and skip it; else False.\n    val match = { u8 c ->\n        skip();\n        if( x >= buf# ) return false;\n        if( buf[x] != c ) return false;\n        x++;\n        return true;\n    };\n\n    // Parse a simple number\n    val number = { ->\n        skip();\n        bool neg = match('-');\n        if( x >= buf# || buf[x] < '0' || '9' < buf[x] ) {\n            bad = true;\n            return 0;\n        }\n        i64 n = 0;\n        while( x < buf# && '0' <= buf[x] & buf[x] <= '9' )\n            n = n*10 + (buf[x++] - '0');\n        return neg ? -n : n;\n    };\n};\n"
